    """Return the n-th Fibonacci number.
    fib(1) == 1, fib(2) == 1 for 1-indexed convention.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

