def fib(n: int) -> int:
    """Return the n-th Fibonacci number using memoization.
    fib(1) == 1, fib(2) == 1 for 1-indexed convention.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")
    memo = {1: 1, 2: 1}
    def helper(k):
        if k in memo:
            return memo[k]
        memo[k] = helper(k - 1) + helper(k - 2)
        return memo[k]
    return helper(n)

