def no_three_consecutive_equal_pairs(s: str) -> bool:
    """
    Returns True if no 3 consecutive chars have any equal pair.
    This means for any index i, the substring s[i:i+3] must not contain
    any adjacent equal characters (i.e., s[i] != s[i+1] and s[i+1] != s[i+2]).
    """
    # Using a generator expression with all() for a functional approach.
    # We iterate over all valid start indices for a 3-char substring.
    return all(
        s[i] != s[i+1] and s[i+1] != s[i+2]
        for i in range(len(s) - 2)
    )

