def counts_pattern(text):
    """
    Returns a dictionary with counts of lowercase letters ('a'..'z')
    that occur at odd indices (0-based) in the text, and also
    counts occurrences per character for splitting the text into
    segments by non-lowercase characters.
    """
    from collections import Counter

    # Count lowercase letters at odd indices
    odd_index_counts = Counter()
    for i, ch in enumerate(text):
        if 'a' <= ch <= 'z' and i % 2 == 1:
            odd_index_counts[ch] += 1

    # Split text into segments by non-lowercase letters
    segments = []
    current = []
    for ch in text:
        if 'a' <= ch <= 'z':
            current.append(ch)
        else:
            if current:
                segments.append(''.join(current))
                current = []
    if current:
        segments.append(''.join(current))

    # Count occurrences of each lowercase letter in all segments
    splits_counts = Counter()
    for seg in segments:
        for ch in seg:
            splits_counts[ch] += 1

    return {
        'odd_index_counts': dict(odd_index_counts),
        'splits_counts': dict(splits_counts),
        'segments': segments
    }

